"4-Achs-Sätze mit X/Y/Z und A zusammen: Viele Steuerungen rechnen dort Grad wie Millimeter, der Fräser läuft dann am Werkstück zu langsam oder zu schnell. „Umgerechnet“ schreibt den F-Wert so, dass eine solche Steuerung den gewünschten Vorschub an der Schneide fährt. „Zeitreziprok“ schaltet auf G93 und gibt in jedem Satz 1/Zeit an – eindeutig, wenn die Steuerung G93 kennt.":"Bloques de 4 ejes con X/Y/Z y A juntos: muchos controles cuentan ahí los grados como milímetros, y la fresa avanza entonces demasiado lento o demasiado rápido en la pieza. «Convertido» escribe el valor F de modo que un control así ejecute el avance deseado en el filo. «Tiempo inverso» cambia a G93 e indica 1/tiempo en cada bloque – inequívoco si el control conoce G93.",
