"Alle Einstellungen, Symbolleisten-Anpassungen und eigenen Tastenkürzel auf die Vorgaben zurücksetzen?\n\nEigene Werkzeugbibliotheken, Materialien und Vorlagen bleiben erhalten.":"¿Restablecer a los valores predeterminados todas las preferencias, personalizaciones de la barra de herramientas y atajos de teclado propios?\n\nLas bibliotecas de herramientas, materiales y plantillas propios se conservan.",
"Alle Flächen des Merkmals wählen: bei einer Bohrung die Wand (und Senkung, Boden), bei einer Tasche Wände und Boden, bei einem Zapfen Mantel und Stirnfläche. Das Merkmal wandert um X/Y/Z; die alte Stelle wird geschlossen. Geht auch bei importierten STEP-Teilen ohne Verlauf. Beim ersten Mal lädt der große Geometriekern (einige Sekunden).":"Seleccionar todas las caras de la operación: en un agujero la pared (y el avellanado, el fondo), en una cajera las paredes y el fondo, en un saliente la cara lateral y la frontal. La operación se desplaza en X/Y/Z; la posición anterior se cierra. También funciona con piezas STEP importadas sin historial. La primera vez se carga el núcleo geométrico grande (unos segundos).",
"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Seleccione todas las caras que deben desaparecer (en una cajera, paredes y fondo; en un agujero, la pared; en un empalme, la superficie redondeada). Las caras vecinas se prolongan sobre el hueco. El paso se recalcula al cambiar el cuerpo; la primera vez se carga para ello el núcleo geométrico completo (unos segundos).",
