"Durchgangspunkte klicken. Auf den Startpunkt klicken schließt die Spline, Enter beendet sie offen.":"Haga clic en los puntos de paso. Un clic en el punto inicial cierra la spline; Intro la termina abierta.",
"Durchgehend":"Pasante",
"Durchgereichter NC-Code wird unverändert ausgegeben und nicht geprüft – er muss zur Steuerung passen und darf das Werkzeug nicht in eine unbekannte Lage bringen":"El código NC transferido se emite sin cambios y no se comprueba – debe ser adecuado para el control y no debe llevar la herramienta a una posición desconocida",
"Durchgänge":"Pasadas",
"Durchlaufender Radius: Die gewählten Kanten müssen eine zusammenhängende Kette bilden":"Radio continuo: las aristas seleccionadas deben formar una cadena continua",
