"Ecken":"Esquinas",
"Ecken und Kantenenden rasten beim Anklicken ein. Punkte dienen als Bezug für Ebene durch drei Punkte und Achse durch zwei Punkte.":"Los vértices y extremos de arista se acoplan al hacer clic. Los puntos sirven de referencia para un plano por tres puntos y un eje por dos puntos.",
