"Eigener Befehl „Ein“":"Comando propio «Encendido»",
"Eigener Kurzbefehl für „{0}“ entfernt.":"Atajo personalizado de «{0}» eliminado.",
"Eigener Nullpunkt je Teil":"Origen propio por pieza",
