"Eilgang ins Material":"Avance rápido dentro del material",
"Eilgang nur auf Rückzugs-/Sicherheitshöhe":"Rápido solo a la altura de retirada/seguridad",
"Eilgang, Strahl aus":"Avance rápido, haz apagado",
"Eilgangbewegungen beibehalten":"Mantener movimientos rápidos",
"Eilgangrückzug zulassen":"Permitir retirada en rápido",
"Eilgangweg":"Recorrido en rápido",
"Ein Gelenk anlegen: ZUSAMMENBAU → „Gelenk“ (J), erst das bewegliche Teil, dann das feste anklicken, Art „Drehgelenk“ oder „Schiebegelenk“.":"Crear una unión: ENSAMBLAR → «Unión» (J), hacer clic primero en la pieza móvil y luego en la fija, tipo «Revolución» o «Deslizante».",
"Ein Rechteck zeichnen: Werkzeug „Rechteck“ (R), zwei Ecken anklicken. Maße kann man direkt eintippen, z. B. 80 und 50.":"Dibujar un rectángulo: herramienta «Rectángulo» (R), hacer clic en dos esquinas. Las cotas se pueden escribir directamente, p. ej. 80 y 50.",
"Ein Rechtsklick in einen Dialog (nicht in ein Eingabefeld) drückt dessen OK-Schaltfläche":"Un clic derecho en un diálogo (fuera de un campo de entrada) pulsa su botón Aceptar",
"Ein anderes gespeichertes Design als Komponente einfügen":"Insertar otro diseño guardado como componente",
"Ein eingefügter Satz verschiebt alle folgenden Satznummern – so zählen sie nicht als Änderung":"Un bloque insertado desplaza todos los números de bloque siguientes – así no cuentan como cambio",
"Ein gerollter Rand über 350° schließt sich zum Rohr – das ist so nicht herstellbar":"Un borde enrollado de más de 350° se cierra formando un tubo: así no se puede fabricar",
"Ein geschlossenes Netz in einen Volumenkörper umwandeln (jedes Dreieck wird eine Fläche)":"Convertir una malla cerrada en un cuerpo sólido (cada triángulo se convierte en una cara)",
"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Una fresa redonda deja su radio en cada esquina interior, de modo que una pieza complementaria de aristas vivas no encaja. El alivio entra brevemente en la esquina y vuelve en cada esquina interior viva.{0}{1}",
"Ein verbundener Agent arbeitet am geöffneten Entwurf: Er liest und ändert die Zeitachse, fragt Körper, Volumen und Fehler ab, holt Normteile aus dem Bauteilkatalog, lässt sich ein Bild der Ansicht geben, exportiert STEP oder STL, legt Werkzeuge und Fertigungsoperationen an und gibt das NC-Programm aus – das vor dem ersten Schnitt zu prüfen bleibt. Auf Dateien, Einstellungen und andere Entwürfe hat er keinen Zugriff. Jede Änderung ist ein Schritt, den Strg+Z zurücknimmt.":"Un agente conectado trabaja en el diseño abierto: lee y modifica la línea de tiempo, consulta cuerpos, volúmenes y errores, obtiene piezas normalizadas del catálogo de piezas, solicita una imagen de la vista, exporta STEP o STL, crea herramientas y operaciones de fabricación y genera el programa NC, que debe comprobarse antes del primer corte. No tiene acceso a archivos, preferencias ni a otros diseños. Cada cambio es un paso que Ctrl+Z deshace.",
"Ein zweiter Klick auf die Schaltfläche des Zeichenwerkzeugs schaltet zurück auf Auswählen":"Un segundo clic en el botón de la herramienta de dibujo vuelve a Seleccionar",
"Ein-/Ausblenden":"Mostrar/Ocultar",
"Ein-/Ausfahrten und Übergänge":"Entradas, salidas y transiciones",
"Einblenden":"Mostrar",
"Einblendungen":"Superposiciones",
"Eine Bahn entlang jeder Innenecke/Hohlkehle, in der das Werkzeug zwei Flächen zugleich berührt – zum Ausräumen nach dem Schlichten.":"Una trayectoria a lo largo de cada esquina interior o acuerdo donde la herramienta toca dos caras a la vez; para limpiar el material residual tras el acabado.",
"Eine Bearbeitung anlegen, z. B. FRÄSEN → „2D-Kontur“ oder „Planfräsen“, Werkzeug wählen, OK.":"Crear una operación, p. ej. FRESADO → «Contorno 2D» o «Planeado», elegir una herramienta, OK.",
"Eine Bohrung setzen: „Bohrung“ (H), auf die Oberseite klicken, Durchmesser wählen, OK. (Eine Extrusion mit „Ausschneiden“ zählt auch.)":"Colocar un agujero: «Agujero» (H), hacer clic en la cara superior, elegir un diámetro, OK. (Una extrusión con «Cortar» también cuenta.)",
"Eine Explosionsansicht braucht mindestens zwei Körper.":"Una vista explosionada necesita al menos dos cuerpos.",
"Eine Explosionsansicht öffnen: „Explosionsansicht“ – „Montageanleitung“ macht daraus eine Seite mit Bildern.":"Abrir una vista explosionada: «Vista explosionada» – «Instrucciones de montaje» crea a partir de ella una página con imágenes.",
"Eine Fläche, Bohrung oder einen Zapfen anklicken.":"Haga clic en una cara, un agujero o un saliente.",
"Eine Fläche, Bohrung oder einen Zapfen eines Körpers anklicken.":"Haga clic en una cara, un agujero o un saliente de un cuerpo.",
"Eine Konfiguration merkt sich die Ausdrücke aller Parameter unter einem Namen – etwa „kurz“ und „lang“. Ein Klick stellt die Variante wieder her.":"Una configuración guarda las expresiones de todos los parámetros bajo un nombre, por ejemplo «corto» y «largo». Un clic restaura la variante.",
"Eine Platte mit Bohrung und abgerundeten Kanten – Skizze, Extrusion, Bohrung und Verrundung.":"Una placa con un agujero y aristas redondeadas – boceto, extrusión, agujero y empalme.",
"Eine Seite":"Un lado",
"Eine Seite mit einem Bild je Montageschritt (Explosion rückwärts), druckbar und als PDF":"Una página con una imagen por paso de montaje (explosión en orden inverso), imprimible y en PDF",
"Eine Variante speichern: VERWALTEN → „Konfigurieren“, Name z. B. dünn.":"Guardar una variante: GESTIONAR → «Configurar», nombre p. ej. delgada.",
"Eine der gewählten Kanten oder Flächen wurde nicht mehr gefunden – neu wählen.":"Ya no se encontró una de las aristas o caras seleccionadas – vuelva a seleccionar.",
"Einen Bewegungsablauf anlegen: „Bewegungsablauf“, „+ Schritt“, dann ▶ – „Prüfen“ meldet Zusammenstöße mit Zeitpunkt.":"Crear un estudio de movimiento: «Estudio de movimiento», «+ Paso», luego ▶ – «Comprobar» informa de las colisiones con su instante.",
"Einen Moment – das Modell wird noch berechnet.":"Un momento: el modelo aún se está calculando.",
"Einen Parameter anlegen: VERWALTEN → „Parameter ändern“, „+ Parameter“, Name z. B. dicke, Wert 10.":"Crear un parámetro: GESTIONAR → «Cambiar parámetros», «+ Parámetro», nombre p. ej. espesor, valor 10.",
