"Erst Parameter anlegen – die Spalten der Tabelle werden den Parametern zugeordnet.":"Cree primero parámetros – las columnas de la tabla se asignan a los parámetros.",
"Erst Parameter anlegen – eine Konfiguration merkt sich deren Werte.":"Cree primero parámetros: una configuración guarda sus valores.",
"Erst Schritte anlegen (oder „Automatisch“).":"Cree primero pasos (o «Automático»).",
"Erst Schritte anlegen.":"Cree primero pasos.",
"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Haga clic primero en la cara del cuerpo que se mueve y después en la cara de destino del otro cuerpo. El cuerpo se gira y se desplaza hasta que el primer punto de clic quede sobre el segundo y las caras se apoyen una sobre otra.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Haga clic primero en la arista del cuerpo que se mueve y después en la arista de destino del otro cuerpo. Las aristas rectas quedan coincidentes (centro sobre centro); en las aristas circulares (agujero y espiga) los ejes se orientan igual y los centros se unen.",
"Erst ein Setup anlegen.":"Cree primero una configuración.",
"Erst ein Setup mit Operationen anlegen.":"Cree primero una configuración con operaciones.",
"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"Seleccione primero un boceto o un plano de construcción; entonces Ctrl+8 lo mira perpendicularmente.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"Cree primero un cuerpo en DISEÑO o inserte una malla (STL).",
"Erst einen Körper in KONSTRUKTION erstellen.":"Cree primero un cuerpo en DISEÑO.",
"Erst einen Namen für das Profil eingeben.":"Introduzca primero un nombre para el perfil.",
"Erst in eine Vorlage klicken, dann den Platzhalter wählen":"Haga clic primero en una plantilla y luego elija el marcador de posición",
"Erste Ecke klicken, dann gegenüberliegende Ecke.":"Haga clic en la primera esquina y luego en la esquina opuesta.",
"Erstellen":"Crear",
"Erstellt {0}":"Creado {0}",
"Ersten Bogenmittelpunkt, zweiten Bogenmittelpunkt, dann Breite klicken.":"Haga clic en el centro del primer arco, en el centro del segundo arco y luego en el ancho.",
"Ersten Punkt gewählt – jetzt den zweiten anklicken.":"Primer punto seleccionado: ahora haga clic en el segundo.",
"Erster Q-Parameter":"Primer parámetro Q",
"Erster Werkzeugaufruf":"Primera llamada de herramienta",
"Erstes NC-Programm wählen …":"Elegir el primer programa CN …",
"Erstes Teil: Halteplatte":"Primera pieza: placa de soporte",
"Erzeugendes Feature in Zeitachse suchen":"Buscar la operación generadora en la línea de tiempo",
"Erzeugt eine neue Fläche im Abstand zu den gewählten Flächen (negativ = nach innen). Der Körper bleibt unverändert.":"Crea una superficie nueva a una distancia de las caras seleccionadas (negativo = hacia dentro). El cuerpo no cambia.",
"Erzeugt einen Tastzyklus (Heidenhain TCH PROBE 417/412/413/411/410, Fanuc Renishaw G65 P98xx).":"Genera un ciclo de palpado (Heidenhain TCH PROBE 417/412/413/411/410, Fanuc Renishaw G65 P98xx).",
"Es braucht einen Körper – falls keiner da ist: Datei → Beispiele, oder zuerst „Erstes Teil“.":"Se necesita un cuerpo – si no hay ninguno: Archivo → Ejemplos, o primero «Primera pieza».",
"Es braucht einen Körper – falls noch keiner da ist, zuerst die Aufgabe „Erstes Teil“ machen.":"Se necesita un cuerpo – si aún no hay ninguno, haga primero la lección «Primera pieza».",
"Es braucht mindestens zwei Körper (z. B. zwei Extrusionen mit „Neuer Körper“).":"Se necesitan al menos dos cuerpos (p. ej. dos extrusiones con «Cuerpo nuevo»).",
