"Formfräser: zuerst in KONSTRUKTION eine Skizze mit dem Schneidenprofil zeichnen (rechte Hälfte, Werkzeugachse = Skizzen-Y-Achse, Spitze unten).":"Fresa de forma: primero dibuje en DISEÑO un boceto con el perfil de corte (mitad derecha, eje de la herramienta = eje Y del boceto, punta abajo).",
