"Gemeinsame Schnittkanten nur einmal schneiden":"Cortar una sola vez los bordes de corte comunes",
"Gemeinsame Schnittkanten: liegen zwei Zuschnitte genau eine Schnittfuge auseinander (beim Schachteln als Abstand die Schnittfuge eintragen), fällt ihre Bahn auf der gemeinsamen Kante zusammen und wird nur einmal geschnitten. Der Anschnitt liegt nie in einem Nachbarteil: ist neben einer Kontur kein freier Abfall, wird auf der Kontur eingestochen. Nach „Vorschau“ zeigt ein Bild je Tafel die Bahn, bevor die Dateien gespeichert werden.":"Bordes de corte comunes: si dos piezas recortadas están separadas exactamente por un ancho de corte (al anidar, introduzca el ancho de corte como separación), sus trayectorias coinciden en el borde común y se corta solo una vez. La entrada nunca queda en una pieza vecina: si junto a un contorno no hay desecho libre, se perfora sobre el contorno. Tras «Vista previa», una imagen por plancha muestra la trayectoria antes de guardar los archivos.",
