"Geschafft! Das Teil steht in der Zeitleiste unten – ein Doppelklick auf einen Schritt ändert ihn nachträglich. Weiter geht es mit „Maße als Parameter“ oder „Vom Teil zum NC-Programm“.":"¡Listo! La pieza aparece en la línea de tiempo abajo – un doble clic en un paso permite modificarlo después. Continúe con «Cotas como parámetros» o «De la pieza al programa CN».",
"Geschlossen":"Cerrado",
"Geschlossen (Gehrung)":"Cerrada (inglete)",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Cerrada: las pestañas de dos aristas contiguas llegan hasta la bisectriz de la esquina y dejan ahí la holgura. El alivio de esquina se sitúa donde se cruzan las zonas de plegado, tanto en el desarrollo como en la pieza plegada. Una pestaña en una arista curva también se corta a inglete en una esquina real (allí sin alivio de esquina).",
"Geschlossene Kette {0}":"Cadena cerrada {0}",
"Geschlossene Profile begrenzen den Bereich.":"Los perfiles cerrados delimitan la zona.",
"Geschlossene Profile der aktiven Skizze farbig füllen":"Rellenar de color los perfiles cerrados del boceto activo",
"Geschlossene Profile werden zu ebenen Flächen – z. B. Deckel und Boden, um Flächen anschließend zu einem Körper zusammenzufügen.":"Los perfiles cerrados se convierten en superficies planas, p. ej. tapa y fondo, para coser después las superficies en un cuerpo.",
"Geschnitten ab X":"Seccionado desde X",
"Geschwenkte Bearbeitungsebene":"Plano de mecanizado inclinado",
