"Gespeichert werden Blechdicke {0} mm, Biegeradius innen {1} mm und K-Faktor {2}. Die Regel steht danach bei jedem Blech in der Liste „Blechregel“ – auch in anderen Projekten auf diesem Rechner.":"Se guardan el espesor de chapa {0} mm, el radio de plegado interior {1} mm y el factor K {2}. Después la regla aparece en la lista «Regla de chapa» de cada chapa, también en otros proyectos de este equipo.",
"Gespiegelt":"Simétrico",
"Gestrichelt im DXF/der Skizze: Biegelinien (Anfang und Ende jeder Biegezone). Im DXF liegen sie auf der Ebene BIEGUNG, der Umriss auf Ebene 0.":"Discontinuas en el DXF/boceto: líneas de plegado (inicio y fin de cada zona de plegado). En el DXF están en la capa BIEGUNG y el contorno en la capa 0.",
