"Gewinde als ein Zyklus-Satz: Okuma G71 (gerade Zustellung B0, Gewindetiefe H, erste Zustellung D), Fanuc G76 (Flankenzustellung 60°).":"Rosca en un solo bloque de ciclo: Okuma G71 (penetración recta B0, profundidad de rosca H, primera pasada D), Fanuc G76 (penetración por flanco 60°).",
