"Gewindebohrung":"Agujero roscado",
"Gewindebohrung M6":"Taladro roscado M6",
"Gewindebohrung für {0}":"Agujero roscado para {0}",
"Gewindebohrung für {0} – Skizze":"Agujero roscado para {0} – boceto",
"Gewindebohrung im untersten Teil":"Agujero roscado en la pieza inferior",
"Gewindebohrung im untersten Teil: die Durchgangsbohrung endet, wo das unterste Teil beginnt; dort entsteht das Kernloch mit Gewinde – drei Gewindegänge tiefer, als die Schraube reicht, oder durch das ganze Teil. Liegt nur ein Teil unter dem Punkt, bekommt es das Gewinde von der Fläche an. „Länge passend zur Einschraubtiefe“ nimmt die nächste Länge der Reihe, mit der die Schraube etwa so tief im Gewinde sitzt, wie ihr Gewinde dick ist (Richtwert für Stahl) – aber nie länger, als das Teil dick ist.":"Agujero roscado en la pieza inferior: el agujero pasante termina donde empieza la pieza más baja; allí se crea el agujero de macho con rosca, tres pasos de rosca más profundo de lo que llega el tornillo, o a través de toda la pieza. Si solo hay una pieza bajo el punto, recibe la rosca desde su cara. «Longitud acorde a la profundidad de roscado» toma la siguiente longitud de la serie con la que el tornillo queda enroscado aproximadamente tanto como el grosor de su rosca (valor orientativo para acero), pero nunca más larga que el grosor de la pieza.",
"Gewindebohrung {0} – Einschraubtiefe nur {1} mm":"agujero roscado {0} – profundidad de enrosque de solo {1} mm",
"Gewindebohrung {0}, Einschraubtiefe {1} mm":"agujero roscado {0}, profundidad de enrosque {1} mm",
"Gewindebohrung: gebohrt wird das Kernloch; das Gewinde erscheint als Gewindedarstellung am Modell und mit seinem Namen in der Zeichnung.":"Agujero roscado: se taladra el agujero de núcleo; la rosca aparece como representación de rosca en el modelo y con su designación en el plano.",
