"Gleiche Durchmesser ergeben ein Rohr, verschiedene einen Kegelstumpf. Die Abwicklung wird auf der neutralen Faser gerechnet (Innenfläche + K-Faktor × Blechdicke); beim Runden liegt sie näher an der Blechmitte als beim Abkanten – üblich ist ein K-Faktor von 0,45 bis 0,5. Mit einer Blechregel gelten deren Dicke und K-Faktor. Der Nahtspalt bleibt am größeren Durchmesser offen (0 = stumpf gestoßen, im Körper dann ein Schlitz von 0,01 mm).":"Diámetros iguales dan un tubo; diámetros distintos, un tronco de cono. El desarrollo se calcula sobre la fibra neutra (cara interior + factor K × espesor de chapa); al curvar queda más cerca del centro de la chapa que al plegar; lo habitual es un factor K de 0,45 a 0,5. Con una regla de chapa se aplican su espesor y su factor K. La holgura de costura queda abierta en el diámetro mayor (0 = a tope; en el cuerpo queda entonces una ranura de 0,01 mm).",
"Gleicher Abstand":"Distancia igual",
"Gleichlauf":"Concordancia",
"Gleichmäßige Dreiecke dieser Größe: lange Kanten werden geteilt, danach wird auf die Dreieckszahl eines gleichmäßigen Netzes reduziert. Gut vor dem Glätten oder Formen von Scans.":"Triángulos uniformes de este tamaño: las aristas largas se dividen y después se reduce al número de triángulos de una malla uniforme. Útil antes de suavizar o dar forma a escaneos.",
"Gleichzeitig mit dem Schritt davor":"Simultáneo con el paso anterior",
