"Halbzeug: Nennmaße der Norm, auf jede Länge zugeschnitten. Nicht jede Paarung von Maß und Wanddicke ist bei jedem Händler am Lager. Ein Rohr entlang einer Skizzenlinie – auch um Ecken und Bögen – legt der Befehl „Rohr“ an.":"Semiproducto: medidas nominales de la norma, cortado a cualquier longitud. No todas las combinaciones de medida y espesor de pared están en stock en todos los distribuidores. Un tubo a lo largo de una línea de boceto, también alrededor de esquinas y arcos, se crea con el comando «Tubo».",
