"Heidenhain: an der Steuerung die Datenübertragung über Ethernet freigeben (wie für TNCremo, LSV2, Port 19000); Standardordner TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: Port 21, Ordner z. B. /_N_WKS_DIR oder /NC. Netzwerkordner: Pfad wie \\\\MASCHINE\\NC oder Z:\\NC. DNC: Wandler als TCP-Server (raw), meist Port 4001; an der Steuerung „Abarbeiten extern“, DNC oder TAPE starten.":"Heidenhain: habilitar en el control la transferencia de datos por Ethernet (como para TNCremo, LSV2, puerto 19000); carpeta predeterminada TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: puerto 21, carpeta p. ej. /_N_WKS_DIR o /NC. Carpeta de red: ruta como \\\\MASCHINE\\NC o Z:\\NC. DNC: convertidor como servidor TCP (raw), normalmente puerto 4001; en el control iniciar «Ejecución externa», DNC o TAPE.",
