"JSON kopieren":"Copiar JSON",
"Je Operation zwei Q-Parameter am Programmanfang: der erste verschiebt die Tiefe (DL, + = weniger tief), der zweite das seitliche Aufmaß (DR, + = mehr Aufmaß; wirkt nur bei Radiuskorrektur an der Steuerung RL/RR). An der Maschine eine Zahl ändern statt Sätze suchen.":"Dos parámetros Q por operación al inicio del programa: el primero desplaza la profundidad (DL, + = menos profundo), el segundo el sobremetal lateral (DR, + = más sobremetal; solo actúa con corrección de radio en el control RL/RR). En la máquina se cambia un número en lugar de buscar bloques.",
"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"La primera curva de cada boceto, abierta o cerrada. Las curvas se unen mediante una piel (superficie sin espesor).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Kiemenschlitze werden auf ihrer Linie geschnitten. Haltestege: so viele Stellen je Umriss bleiben stehen (Laser, Plasma, Wasserstrahl: der Strahl setzt dort aus; Fräsen: der Fräser hebt auf halbe Blechdicke), Umrisse unter 40 mm Länge bekommen keine. „Steuerung“ legt fest, womit der Strahl ein- und ausgeschaltet wird; die Einstechzeit steht als G4 im Programm, außer die Steuerung sticht selbst ein. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Un archivo por plancha. La trayectoria discurre junto al contorno, en el desecho, a media anchura de corte (en fresado, medio diámetro de fresa); los recortes van antes del contorno de su pieza y cada contorno comienza con una entrada desde el desecho. Las ranuras de persiana se cortan sobre su línea. Puentes de sujeción: tantos puntos por contorno quedan sin cortar (láser, plasma, chorro de agua: el haz se interrumpe ahí; fresado: la fresa sube hasta media altura del espesor de la chapa); los contornos de menos de 40 mm de longitud no llevan ninguno. «Control» define cómo se enciende y se apaga el haz; el tiempo de perforación aparece como G4 en el programa, salvo que el control perfore por sí mismo. El origen es la esquina inferior izquierda de la plancha; en fresado, Z0 es la cara superior de la chapa. Compruebe el programa en la máquina o en un simulador CNC antes de usarlo.",
"Je Werkzeug alle Teile (weniger Werkzeugwechsel)":"Todas las piezas por herramienta (menos cambios de herramienta)",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Cada eje por separado: haga clic en una arista, una esquina, una cara o un agujero. Los ejes sin definir se toman del punto del material en bruto.",
"Jede Bohrung wird mit ihren Koordinaten einzeln angefahren (X/Y je Bohrung) – kein Lochkreis- oder Rastermuster.":"Cada taladro se aborda por separado con sus coordenadas (X/Y por taladro) – sin patrón de círculo de taladros ni matriz.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Cada operación como subprograma (LBL) al final del programa, llamada con CALL LBL",
"Jede Variante berechnen und als STEP, STL oder 3MF speichern (eine ZIP-Datei)":"Calcular cada variante y guardarla como STEP, STL o 3MF (un archivo ZIP)",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Cada círculo del boceto es el centro de un agujero. Se taladra en sentido contrario a la normal del boceto (hacia el material).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Cada círculo del boceto se repite girándolo alrededor del centro (en coordenadas del boceto): un círculo a la distancia del radio del círculo primitivo da un círculo de agujeros.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Cada círculo del boceto se convierte en una cuadrícula: separaciones en X e Y del boceto (también negativas).",
"Jeder sichtbare Körper wird ein Glied mit Netz (STL, in Metern), Masse und Trägheit, jedes Gelenk ein Gelenk mit Achse und Grenzen. Die jetzige Stellung ist die Nullstellung. Mit einem Paketnamen stehen die Netze im URDF als package://Name/meshes/…, sonst als relativer Pfad.":"Cada cuerpo visible se convierte en un eslabón (link) con malla (STL, en metros), masa e inercia, y cada unión en una unión (joint) con eje y límites. La posición actual es la posición cero. Con un nombre de paquete, las mallas aparecen en el URDF como package://Name/meshes/…; de lo contrario, como ruta relativa.",
"Jedes # im Skizzentext wird durch die Nummer ersetzt, mit Nullen aufgefüllt (SN-#### → SN-{0}). Bei mehreren Teilen in einer Aufspannung bekommt jedes Teil die nächste Nummer: {1}{2}.":"Cada # del texto del boceto se sustituye por el número, rellenado con ceros (SN-#### → SN-{0}). Con varias piezas en una sujeción cada pieza recibe el número siguiente: {1}{2}.",
"Jedes Teil hat seinen eigenen Nullpunkt in der Steuerung (G54, G55 … bzw. Bezugspunkt-Nummer in der Tabelle – Heidenhain Zyklus 247). Alle Nullpunkte vorher an der Maschine setzen.":"Cada pieza tiene su propio origen en el control (G54, G55 … o número de punto de referencia en la tabla – Heidenhain ciclo 247). Fijar antes todos los orígenes en la máquina.",
"Jedes eigene Maß und jeder Toleranzrahmen bekommt eine Nummer in einem Kreis. Die Liste enthält Nennmaß, Toleranz, Höchst- und Mindestmaß und Felder für den Istwert. Maße ohne eigene Toleranz bekommen die Allgemeintoleranz.":"Cada cota propia y cada marco de tolerancia recibe un número en un círculo. La lista contiene medida nominal, tolerancia, medidas máxima y mínima y campos para el valor real. Las cotas sin tolerancia propia reciben la tolerancia general.",
"Jetzigen Stand festhalten":"Guardar el estado actual",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"Ahora un punto en el segundo lado.",
"Jetzt festhalten":"Guardar ahora",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"Ahora cada dirección una vez hasta el tope: deslizar, tirar, pulsar, inclinar, girar (10 s) …",
