"Kalibrieren: einen Abstand größer als 0 angeben.":"Calibrar: indique una distancia mayor que 0.",
"Kalibrieren: ersten Punkt im Bild anklicken (Esc bricht ab).":"Calibrar: haga clic en el primer punto de la imagen (Esc cancela).",
"Kalibrieren: wirklicher Abstand der beiden Punkte (mm)":"Calibrar: distancia real entre los dos puntos (mm)",
"Kalibrieren: zwei Punkte im Bild anklicken, deren Abstand bekannt ist, und den wirklichen Abstand eingeben – das Bild bekommt den richtigen Maßstab.":"Calibrar: haga clic en dos puntos de la imagen cuya distancia conozca e introduzca la distancia real: la imagen recibe la escala correcta.",
