"Kante im Blatt anklicken …":"Haga clic en una arista de la hoja …",
"Kante projiziert":"Arista proyectada",
"Kante {0} (Bogen R{1}, {2} mm)":"Arista {0} (arco R{1}, {2} mm)",
"Kante {0} (Kreis R{1}, {2} mm)":"Arista {0} (círculo R{1}, {2} mm)",
"Kante {0} ({1} mm)":"Arista {0} ({1} mm)",
"Kante {0} ist zu kurz für eine Lasche":"La arista {0} es demasiado corta para una pestaña",
"Kante {0}: Biegewinkel über 180° ist nicht herstellbar.":"Arista {0}: un ángulo de plegado superior a 180° no se puede fabricar.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestaucht (Faltengefahr); der Zuschnitt ist dort eine Näherung.":"Arista {0}: pestaña en una arista curva – su borde se comprime un {1} % al conformar (riesgo de arrugas); el recorte es allí una aproximación.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"Arista {0}: pestaña en una arista curva – su borde se estira un {1} % al conformar (riesgo de grietas); el recorte es allí una aproximación.",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"Arista {0}: la medida de la pestaña {1} mm es menor que el plegado ({2} mm)",
"Kante {0}: der Bogen ist zu eng für diese Lasche":"Arista {0}: el arco es demasiado cerrado para esta pestaña",
"Kante {0}: die Abstände lassen keine Lasche übrig.":"Arista {0}: las distancias no dejan ninguna pestaña.",
"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"Arista {0}: la pestaña cruza una línea de plegado; haga que termine antes del plegado con «Distancia inicio / fin»",
"Kante {0}: die Lasche liegt in einer Biegezone":"Arista {0}: la pestaña está en una zona de plegado",
"Kante {0}: ein Ausschnitt gehört zu einer Lasche, die es nicht gibt.":"Arista {0}: un recorte pertenece a una pestaña que no existe.",
"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Arista {0}: un recorte en la pestaña está a {1} mm del pliegue (menos de 2 × el espesor de chapa) – se deforma al plegar.",
"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Arista {0}: un recorte está a {1} mm del pliegue (menos de 2 × el espesor de la chapa): se deforma al plegar.",
"Kante {0}: ein Ausschnitt ragt über die Lasche hinaus.":"Arista {0}: un recorte sobresale de la pestaña.",
"Kante {0}{1}: Lasche {2} mm ist kürzer als 2 × Blechdicke – auf der Abkantpresse kaum zu biegen.":"Arista {0}{1}: la pestaña de {2} mm es más corta que 2 × el espesor de la chapa: apenas se puede plegar en la plegadora.",
"Kante {0}{1}: Saum {2} mm ist kürzer als 4 × Blechdicke – er lässt sich schlecht zudrücken.":"Arista {0}{1}: el dobladillo de {2} mm es más corto que 4 × el espesor de chapa; es difícil de aplastar.",
"Kante {0}{1}: geschlossener Saum (Innenradius {2} mm) – wird in zwei Hüben gebogen und zugedrückt; harte Werkstoffe reißen dabei an der Außenseite.":"Arista {0}{1}: dobladillo cerrado (radio interior {2} mm); se pliega en dos golpes y se aplasta; los materiales duros se agrietan por el lado exterior.",
"Kanten":"Aristas",
"Kanten (Geraden deckungsgleich, Kreise mittig)":"Aristas (rectas coincidentes, círculos concéntricos)",
"Kanten abrunden: „Verrundung“ (F), einige Kanten anklicken, Radius z. B. 3 mm, OK.":"Redondear aristas: «Empalme» (F), hacer clic en algunas aristas, radio p. ej. 3 mm, OK.",
"Kanten anklicken (erneut klicken entfernt).":"Haga clic en aristas (un nuevo clic las quita).",
"Kanten anklicken zum Hinzufügen oder Entfernen – das Ergebnis erscheint gleich im Modell. Kanten, die vor dem Befehl angeklickt wurden, sind schon gewählt. Eingabe = OK.":"Haga clic en aristas para añadirlas o quitarlas: el resultado aparece enseguida en el modelo. Las aristas seleccionadas antes del comando ya están elegidas. Intro = Aceptar.",
"Kanten im Modell anklicken (erneut klicken entfernt)":"Haga clic en aristas del modelo (otro clic las quita)",
