"Kollisionsform: die konvexe Hülle hat wenige Dreiecke und rechnet in der Simulation schnell, füllt aber Taschen und Bohrungen; der Quader ist am gröbsten. Die Ansicht behält immer das volle Netz.":"Forma de colisión: la envolvente convexa tiene pocos triángulos y se calcula rápido en la simulación, pero rellena cajeras y agujeros; la caja es la más tosca. La vista conserva siempre la malla completa.",
