"Lasche an Lasche: Winkel + biegt in dieselbe Richtung weiter (U-Profil, Falz mit 180°), − in die Gegenrichtung (Z-Stufe, Hutprofil). Saum: der Rand der Lasche wird um 180° auf sich selbst zurückgelegt – offen mit einem Spalt von einer Blechdicke, geschlossen flach zugedrückt; mit − 180° liegt er auf der anderen Seite. Das Feld R ist der Innenradius nur dieser Biegung (leer = wie beim Blech). Für einen Saum direkt an der Plattenkante die Lasche selbst auf 180° stellen. Kröpfung: zwei Biegungen gegeneinander (− 45° und + 45°) – der Rand läuft parallel versetzt weiter; Versatz über die Länge des schrägen Stücks und die Winkel.":"Pestaña sobre pestaña: un ángulo + sigue plegando en la misma dirección (perfil en U, pliegue de 180°), − en la dirección contraria (escalón en Z, perfil de sombrero). Dobladillo: el borde de la pestaña se pliega 180° sobre sí mismo; abierto con una separación de un espesor de chapa, cerrado aplastado a ras; con − 180° queda en el otro lado. El campo R es el radio interior solo de este pliegue (vacío = como en la chapa). Para un dobladillo directamente en el borde de la placa, ajuste la propia pestaña a 180°. Desfase: dos pliegues en sentido contrario (− 45° y + 45°); el borde continúa en paralelo, desplazado. El desplazamiento resulta de la longitud del tramo oblicuo y de los ángulos.",
"Lasche {0}":"Pestaña {0}",
