"Länge L ist die Messlänge aus dem Werkzeug (Nennwert). Die echten Längen an der Maschine oder am Voreinstellgerät messen und eintragen. Heidenhain: Datei nach TNC:\\system\\tooltab kopieren, dann Werkzeugverwaltung → WERKZEUG IMPORT.":"La longitud L es la longitud de medición de la herramienta (valor nominal). Medir las longitudes reales en la máquina o en el banco de preajuste e introducirlas. Heidenhain: copiar el archivo a TNC:\\system\\tooltab, luego gestión de herramientas → TOOL IMPORT.",
