"Macht ein geschlossenes Netz hohl: eine Innenwand im Abstand der Wandstärke kommt dazu – spart Material und Druckzeit. Stellen, die dünner sind als zwei Wandstärken, überschneiden sich danach; für Harzdruck ein Ablaufloch mit „Boolesch“ abziehen.":"Vacía una malla cerrada: se añade una pared interior a la distancia del espesor de pared, lo que ahorra material y tiempo de impresión. Las zonas más delgadas que dos espesores de pared se solapan después; para impresión con resina, reste un orificio de drenaje con «Booleana».",
