"Mehrere Zustellungen und Leerdurchgang gibt es nur als Bahn":"Varias penetraciones y la pasada en vacío solo existen como trayectoria",
"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Varias aristas consecutivas cuentan como un único recorrido: el radio varía desde el inicio de la cadena hasta su final y los puntos de control se dan en % de la longitud total de la cadena. Lo calcula el núcleo geométrico completo.",
"Mehrfachaufspannung":"Varias piezas",
"Mehrfachaufspannung: Nullpunkt von Teil {0} gibt es an dieser Steuerung nicht – nur ein Teil ausgegeben":"Varias piezas: este control no tiene origen para la pieza {0} – solo se genera una pieza",
"Mehrfachaufspannung: Nullpunktverschiebung gibt es in diesem Postprozessor nicht – „Eigener Nullpunkt je Teil“ wählen; nur ein Teil ausgegeben":"Varias piezas: este posprocesador no tiene desplazamiento de origen – elegir «Origen propio por pieza»; solo se genera una pieza",
"Meine Designs · {0}":"Mis diseños · {0}",
"Meine Werkzeuge":"Mis herramientas",
"Meldet Bahnen, die tiefer schneiden als das Modell an dieser Stelle (Schaft-, Plan-, Kugel- und Torusfräser, Fasenfräser und Bohrer mit ihrem Kegel; 3-Achs-Bewegungen). Ein Schnitt, der nicht im Modell steht – Gravur, Eckenfreistich, Tasche nur aus einer Skizze – wird ebenfalls gemeldet.":"Avisa de las trayectorias que cortan más profundo que el modelo en ese punto (fresas cilíndricas, de planear, esféricas y toroidales, fresas de chaflanar y brocas con su cono; movimientos de 3 ejes). También se avisa de un corte que no está en el modelo – grabado, alivio de esquina, cajera creada solo a partir de un boceto.",
"Meldung auf dem Bildschirm der Steuerung: Fanuc und LinuxCNC als (MSG, …), Sinumerik als MSG(\"…\"), sonst als Kommentar.":"Mensaje en la pantalla del control: Fanuc y LinuxCNC como (MSG, …), Sinumerik como MSG(\"…\"), en los demás casos como comentario.",
