"Nur Rechteck- und Kreistaschen gehen als Steuerungszyklus":"Solo las cajeras rectangulares y circulares funcionan como ciclo del control",
"Nur Skizze":"Solo boceto",
"Nur das Ende eines Linienzugs lässt sich stutzen oder verlängern.":"Solo el extremo de una polilínea se puede recortar o alargar.",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"Mecanizar solo lo que una fresa mayor ha dejado en las esquinas.",
"Nur die Registerkarten zeigen":"Mostrar solo las pestañas",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Repasar solo las zonas del contorno que una fresa mayor no ha alcanzado (esquinas interiores, zonas estrechas). Sin arcos de entrada/salida, puentes de sujeción ni pasadas de acabado; compensación en el ordenador.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Solo donde no llegó la herramienta de referencia: zonas planas en paralelo, zonas empinadas como línea de nivel. Con una herramienta de la lista también cuenta su forma; por ejemplo, lo que una fresa tórica deja en los acuerdos.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Solo las caras planas pueden servir como plano de boceto.",
"Nur ebene Flächen können extrudiert werden":"Solo se pueden extruir caras planas",
"Nur ebene Flächen lassen sich ersetzen":"Solo se pueden sustituir caras planas",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"Solo se pueden desplazar caras planas y cilíndricas (agujeros, pivotes)",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"Solo caras planas orientadas hacia arriba, hacia la herramienta (horizontales en esta configuración).",
"Nur für Außen-Drehmeißel":"Solo para herramientas de torneado exterior",
"Nur gerade Nuten gehen als Steuerungszyklus (Linie aus zwei Punkten oder Langloch)":"Solo las ranuras rectas se emiten como ciclo del control (línea de dos puntos o ranura oblonga)",
"Nur in Operationen verwendete":"Solo las usadas en operaciones",
"Nur in der Desktop-App":"Solo en la aplicación de escritorio",
"Nur in diesem Projekt":"Solo en este proyecto",
"Nur lesen":"Solo lectura",
"Nur lesen: der Agent sieht Entwurf, Modell, Bilder und NC-Programme, kann aber nichts ändern":"Solo lectura: el agente ve el diseño, el modelo, las imágenes y los programas NC, pero no puede cambiar nada",
"Nur mit Korrektur „Im Rechner“.":"Solo con corrección «En el ordenador».",
"Nur mit Kugelfräser. Das Werkzeug neigt sich zur Flächennormalen, höchstens um die größte Neigung; wo Schaft oder Halter das Teil berühren würden, richtet es sich auf. Ausgabe als Werkzeugvektor (Heidenhain, Sinumerik, Fanuc), sonst als 3-Achs-Bahn.":"Solo con fresa esférica. La herramienta se inclina hacia la normal de la superficie, como máximo la inclinación máxima; donde el mango o el portaherramientas tocarían la pieza, se endereza. Salida como vector de herramienta (Heidenhain, Sinumerik, Fanuc); si no, como trayectoria de 3 ejes.",
"Nur stärkste Achse":"Solo el eje dominante",
