"Prägung {0}: die Kontur ist schmaler als 2 × Blechdicke – es bleibt kein Hohlraum.":"Estampado {0}: el contorno es más estrecho que 2 × el espesor de chapa – no queda ninguna cavidad.",
"Prägung {0}: lässt sich so nicht formen":"Estampado {0}: no se puede conformar así",
"Prägung {0}: mit dieser Wandschräge lässt sie sich nicht formen":"Estampado {0}: no se puede conformar con esta inclinación de pared",
"Prägung {0}: {1} mm ist höher als 3 × Blechdicke – mit senkrechter Wand reißt das Blech.":"Estampado {0}: {1} mm supera 3 × el espesor de chapa – con pared vertical la chapa se rompe.",
"Prägung: die Kontur wird nicht ausgeschnitten, sondern um die Höhe aus der Platte gedrückt; das zweite Feld ist die Wandschräge (0° = senkrecht). Senkprägung: der Rand einer runden Bohrung wird zu einem 90°-Kegel gedrückt – für Senkschrauben in dünnem Blech (− nach unten: Schraube von oben).":"Estampado: el contorno no se recorta, sino que se empuja fuera de la placa la altura indicada; el segundo campo es la inclinación de pared (0° = vertical). Avellanado embutido: el borde de un agujero redondo se embute formando un cono de 90° – para tornillos de cabeza avellanada en chapa fina (− hacia abajo: tornillo desde arriba).",
