"Schraubstock: die Backen greifen quer zur X-Achse des Setups (an Y-min und Y-max des Rohteils); 0 = Größe und Spanntiefe passend wählen. Die Spannmittel werden einfache Körper am Ende der Zeitleiste und hier als Spannmittel eingetragen: Halter- und Kollisionsprüfung, Sicherheitsabstände und Einrichteblatt berücksichtigen sie.":"Tornillo de banco: las mordazas sujetan transversalmente al eje X de la configuración (en Y-mín. e Y-máx. del material en bruto); 0 = elegir tamaño y profundidad de sujeción automáticamente. Los útiles de sujeción se convierten en cuerpos simples al final de la línea de tiempo y se añaden aquí como útiles de sujeción: la comprobación de portaherramientas y colisiones, las distancias de seguridad y la hoja de preparación los tienen en cuenta.",
