"Tauchschruppen":"Desbaste por penetración",
"Tauchschruppen braucht ein Werkzeug mit flacher Stirn (Schaft-, Plan- oder Tauchfräser)":"El desbaste por penetración necesita una herramienta de frente plano (fresa de mango, de planear o de penetración)",
"Tauchschruppen: senkrechte Tauchgänge Reihe für Reihe – für lange Werkzeuge und tiefe Kavitäten":"Desbaste por penetración: penetraciones verticales fila por fila – para herramientas largas y cavidades profundas",
"Teil 1 liegt normalerweise auf dem Nullpunkt (0, 0, 0). Die anderen werden mit einer Nullpunktverschiebung angefahren (Heidenhain Zyklus 7, Fanuc/LinuxCNC G52, Sinumerik TRANS). Vor jedem Wechsel geht das Werkzeug auf die sichere Höhe.":"La pieza 1 está normalmente en el origen (0, 0, 0). Las demás se alcanzan con un desplazamiento de origen (Heidenhain ciclo 7, Fanuc/LinuxCNC G52, Sinumerik TRANS). Antes de cada cambio la herramienta sube a la altura de seguridad.",
