"Teilkreis Ø {0} · Kopfkreis Ø {1} · Fußkreis Ø {2} · Steigung {3} mm · Steigungswinkel {4}°":"Círculo primitivo Ø {0} · círculo de cabeza Ø {1} · círculo de pie Ø {2} · paso de hélice {3} mm · ángulo de avance {4}°",
"Teilt Kanten, die länger sind, in der Mitte (je Durchgang einmal) – die Form bleibt gleich. 0 teilt jede Kante: jedes Dreieck wird zu vier. Sinnvoll vor dem Glätten grober Netze.":"Divide por la mitad las aristas más largas (una vez por pasada); la forma no cambia. 0 divide todas las aristas: cada triángulo se convierte en cuatro. Útil antes de suavizar mallas toscas.",
"Teilt den Körper an der Ebene in zwei Körper.":"Divide el cuerpo en dos cuerpos por el plano.",
