"Verschleiß":"Desgaste",
"Verschraubung: Scheiben und Mutter kommen mit der Schraube in einem Zug an jede angeklickte Bohrung. Die Klemmdicke ist die Länge der Bohrung – durch mehrere Teile hindurch, wenn ihre Bohrungen fluchten und aneinanderstoßen. Mit Mutter wird die kürzeste Vorzugslänge vorgeschlagen, bei der die Schraube zwei Gewindegänge aus der Mutter ragt.":"Unión atornillada: las arandelas y la tuerca se colocan junto con el tornillo, de una sola vez, en cada agujero seleccionado. El espesor sujeto es la longitud del agujero – a través de varias piezas si sus agujeros están alineados y contiguos. Con tuerca se propone la longitud preferente más corta con la que el tornillo sobresale dos filetes de la tuerca.",
