"Verschraubung: {0} – {1}; die Schraube ist für die Klemmdicke {2} mm zu kurz (nötig: {3} mm)":"Unión atornillada: {0} – {1}; el tornillo es demasiado corto para el espesor sujeto de {2} mm (necesario: {3} mm)",
