"Wie fein Körper für STL, 3MF und den Slicer in Dreiecke zerlegt werden: Abweichung von der wahren Fläche als Anteil der Körpergröße. Netze bleiben, wie sie sind.":"Con qué finura se descomponen los cuerpos en triángulos para STL, 3MF y el Slicer: desviación respecto a la superficie real como proporción del tamaño del cuerpo. Las mallas se mantienen como están.",
"Wie fein Zylinder, Kugeln und Rundungen in der Ansicht aus Dreiecken bestehen. Feiner sieht runder aus, rechnet bei großen Modellen aber länger. Der Export hat eine eigene Einstellung (3D-Druck).":"Cuán finamente se componen de triángulos los cilindros, esferas y empalmes en la vista. Más fino se ve más redondo, pero tarda más en modelos grandes. La exportación tiene su propio ajuste (impresión 3D).",
"Wie im System":"Según el sistema",
"Wie lange die Schneide schneiden darf, bevor sie getauscht wird. Das Fenster „Bearbeitungszeit“ rechnet daraus, wie viele Teile noch möglich sind.":"Cuánto tiempo puede cortar el filo antes de cambiarlo. La ventana «Tiempo de mecanizado» calcula con ello cuántas piezas son aún posibles.",
