"Zahnform nach Tredgold (Ersatz-Stirnrad auf dem Rückenkegel), gerade Zähne. Das große Ende liegt in der Grundebene, die Zähne laufen zur Kegelspitze. Für Darstellung, 3D-Druck und Fräsen aus dem Vollen; geschliffene Kegelräder brauchen die Daten des Herstellers.":"Perfil del diente según Tredgold (engranaje recto equivalente sobre el cono complementario), dientes rectos. El extremo mayor queda en el plano base, los dientes van hacia el vértice del cono. Para representación, impresión 3D y fresado desde macizo; los engranajes cónicos rectificados necesitan los datos del fabricante.",
"Zahnrad: Stirnrad gerade / schräg / Pfeil, Hohlrad, Zahnstange, Kegelrad, Schnecke, Schneckenrad, Kettenrad":"Engranaje: cilíndrico recto / helicoidal / en espiga, engranaje interior, cremallera, engranaje cónico, tornillo sin fin, rueda de tornillo sin fin, piñón de cadena",
