"Zum Vereinen braucht es zwei Netzkörper.":"Para combinar se necesitan dos cuerpos de malla.",
"Zungen stehen am freien Ende der Lasche über und kommen in den Zuschnitt. „Schlitze als Skizze“ legt die passenden Schlitze dort an, wo die Zungen stehen – je Ebene eine Skizze, jeder Schlitz ringsum um das Spiel größer als die Zunge. In dieser Skizze den Umriss des Gegenstücks zeichnen und daraus ein Blech oder eine Extrusion machen: die Schlitze werden Ausschnitte. Das Gegenstück liegt auf den Laschenenden auf; die Zungenlänge ist üblich gleich seiner Dicke.":"Las lengüetas sobresalen en el extremo libre de la pestaña y pasan a la pieza cortada. «Ranuras como boceto» crea las ranuras correspondientes donde están las lengüetas – un boceto por plano, con cada ranura mayor que la lengüeta en la holgura por todo su contorno. Dibuje en este boceto el contorno de la pieza complementaria y cree a partir de él una chapa o una extrusión: las ranuras se convierten en recortes. La pieza complementaria se apoya en los extremos de las pestañas; la longitud de las lengüetas suele ser igual a su espesor.",
